package main

import (
	"fmt"
	"strings"
)

// RepoGenerator emits per-table Go list/pagination repo code (package <module>db)
// that delegates to internal/shared/repolist. It replaces pgtempl's List/ListCount
// SQL: the repo builds dynamic SQL and scans via pgx.RowToStructByName.
type RepoGenerator struct {
	Package       string // output package, e.g. "catalogdb"
	IncludeSchema bool   // mirror pgtempl: schema-prefix exported names
}

// repoImports tracks which optional imports the generated file needs.
type repoImports struct {
	uuid bool
	null bool
	time bool
}

// filterField is one column's contribution to the filter struct + bindConds.
type filterField struct {
	structLines []string // Go struct field declarations
	bindLines   []string // bindConds body statements
}

// GenerateRepo returns the full Go source for one table, or "" to skip it
// (key-only ledgers and vector tables have no meaningful generic list).
func (g *RepoGenerator) GenerateRepo(table *Table) string {
	if len(table.UpdatableColumns()) == 0 || table.HasVectorColumn() {
		return ""
	}

	model := toPascalCase(table.Schema) + toPascalCase(table.Name)
	suffix := toPascalCase(table.Name)
	if g.IncludeSchema {
		suffix = model
	}
	listFunc := "List" + suffix
	filterType := listFunc + "Params"
	bindFunc := lowerFirst(suffix) + "ListConds"
	specFunc := lowerFirst(suffix) + "ListSpec"

	var imp repoImports
	var structLines, bindLines []string
	for _, col := range table.FilterableColumns() {
		ff, ok := buildFilterField(col, &imp)
		if !ok {
			continue
		}
		structLines = append(structLines, ff.structLines...)
		bindLines = append(bindLines, ff.bindLines...)
	}

	whitelist := buildWhitelist(table)

	var b strings.Builder
	fmt.Fprintf(&b, "// Code generated by pgtempl; DO NOT EDIT.\npackage %s\n\n", g.Package)
	b.WriteString(repoImportBlock(imp))

	// Params struct. Embeds paginate.Params (page/cursor/sort/limit) so one
	// value carries both pagination and filters; zero Params = fetch all.
	fmt.Fprintf(&b, "// %s filters %s. Each slice field is an IN/ANY match;\n", filterType, table.FullName())
	fmt.Fprintf(&b, "// *From/*To pairs are inclusive range bounds. Zero value = no filter.\n")
	fmt.Fprintf(&b, "type %s struct {\n\tpaginate.Params\n\n%s\n}\n\n", filterType, strings.Join(structLines, "\n"))

	// bindConds.
	fmt.Fprintf(&b, "func %s(f %s, conds *[]string, args pgx.NamedArgs) {\n%s\n}\n\n",
		bindFunc, filterType, strings.Join(bindLines, "\n"))

	// Spec builder.
	fmt.Fprintf(&b, "func %s(f %s) repolist.Spec[%s] {\n", specFunc, filterType, model)
	fmt.Fprintf(&b, "\treturn repolist.Spec[%s]{\n", model)
	fmt.Fprintf(&b, "\t\tTable: `%s`,\n", table.FullName())
	fmt.Fprintf(&b, "\t\tPK: %q,\n", pkLogical(table))
	fmt.Fprintf(&b, "\t\tWhitelist: paginate.Whitelist{\n%s\n\t\t},\n", whitelist)
	fmt.Fprintf(&b, "\t\tBindConds: func(conds *[]string, args pgx.NamedArgs) { %s(f, conds, args) },\n", bindFunc)
	b.WriteString("\t}\n}\n\n")

	// Method on *Queries — same call style as every other sqlc query (q.db is
	// the connection), so callers use b.storage.Querier().List<Table>(f).
	fmt.Fprintf(&b, "// %s runs offset (?page) or cursor (?cursor/?sort) pagination over %s.\n", listFunc, table.FullName())
	fmt.Fprintf(&b, "func (q *Queries) %s(ctx context.Context, f %s) (paginate.PaginateResult[%s], error) {\n",
		listFunc, filterType, model)
	fmt.Fprintf(&b, "\treturn repolist.List(ctx, q.db, %s(f), f.Params)\n}\n", specFunc)

	return b.String()
}

// buildFilterField produces the struct fields + bindConds for one column.
// Returns ok=false for unsupported types (skipped — hand-write if needed).
func buildFilterField(col *Column, imp *repoImports) (filterField, bool) {
	elem, ok := goElemType(col, imp)
	if !ok {
		return filterField{}, false
	}
	field := toPascalCase(col.Name)
	q := col.Quoted()

	ff := filterField{
		structLines: []string{fmt.Sprintf("\t%s []%s", field, elem)},
		bindLines: []string{fmt.Sprintf(
			"\tif len(f.%s) > 0 {\n\t\t*conds = append(*conds, `%s = ANY(@%s)`)\n\t\targs[%q] = f.%s\n\t}",
			field, q, col.Name, col.Name, field)},
	}

	if col.IsRangeFilterable() {
		nullType, accessor := goNullType(col)
		imp.null = true
		ff.structLines = append(ff.structLines,
			fmt.Sprintf("\t%sFrom %s", field, nullType),
			fmt.Sprintf("\t%sTo %s", field, nullType))
		ff.bindLines = append(ff.bindLines,
			fmt.Sprintf("\tif f.%sFrom.Valid {\n\t\t*conds = append(*conds, `%s >= @%s_from`)\n\t\targs[%q] = f.%sFrom%s\n\t}",
				field, q, col.Name, col.Name+"_from", field, accessor),
			fmt.Sprintf("\tif f.%sTo.Valid {\n\t\t*conds = append(*conds, `%s <= @%s_to`)\n\t\targs[%q] = f.%sTo%s\n\t}",
				field, q, col.Name, col.Name+"_to", field, accessor))
	}
	return ff, true
}

// buildWhitelist emits the sortable-column whitelist entries (field: SortCol).
func buildWhitelist(table *Table) string {
	var lines []string
	for _, col := range table.Columns {
		if !sortable(col) {
			continue
		}
		lines = append(lines, fmt.Sprintf("\t\t\t%q: {Col: `%s`, Cast: %q},", col.Name, col.Quoted(), cursorCast(col)))
	}
	return strings.Join(lines, "\n")
}

func repoImportBlock(imp repoImports) string {
	var ext []string
	if imp.uuid {
		ext = append(ext, `"github.com/google/uuid"`)
	}
	ext = append(ext, `"github.com/jackc/pgx/v5"`)
	if imp.null {
		ext = append(ext, `"github.com/guregu/null/v6"`)
	}

	std := []string{`"context"`}
	if imp.time {
		std = append(std, `"time"`)
	}
	internal := []string{
		`"shopnexus-server/internal/shared/paginate"`,
		`"shopnexus-server/internal/shared/repolist"`,
	}

	var b strings.Builder
	b.WriteString("import (\n")
	b.WriteString("\t" + strings.Join(std, "\n\t") + "\n\n")
	b.WriteString("\t" + strings.Join(ext, "\n\t") + "\n\n")
	b.WriteString("\t" + strings.Join(internal, "\n\t") + "\n")
	b.WriteString(")\n\n")
	return b.String()
}

// --- type mapping ---

func baseType(col *Column) string {
	t := strings.ToLower(col.Type)
	if i := strings.IndexByte(t, '('); i != -1 {
		t = t[:i]
	}
	return strings.TrimSpace(t)
}

func isEnum(col *Column) bool {
	// resolveTypeName joins schema-qualified user types as "schema.name";
	// built-ins have no dot.
	return strings.Contains(baseType(col), ".")
}

func enumGoName(col *Column) string {
	parts := strings.Split(baseType(col), ".")
	var b strings.Builder
	for _, p := range parts {
		b.WriteString(toPascalCase(p))
	}
	return b.String()
}

func enumQualifiedCast(col *Column) string {
	parts := strings.Split(baseType(col), ".")
	for i, p := range parts {
		parts[i] = `"` + p + `"`
	}
	return strings.Join(parts, ".")
}

// goElemType returns the non-null Go type for an IN-slice element, marking any
// import it needs. ok=false for types we don't filter on generically.
func goElemType(col *Column, imp *repoImports) (string, bool) {
	switch baseType(col) {
	case "uuid":
		imp.uuid = true
		return "uuid.UUID", true
	case "text", "varchar", "bpchar", "char", "citext":
		return "string", true
	case "int8", "bigint", "bigserial":
		return "int64", true
	case "int4", "integer", "int", "serial":
		return "int32", true
	case "int2", "smallint":
		return "int16", true
	case "float8", "double precision", "double":
		return "float64", true
	case "float4", "real":
		return "float32", true
	case "bool", "boolean":
		return "bool", true
	case "timestamptz", "timestamp", "date", "timestamp with time zone", "timestamp without time zone":
		imp.time = true
		return "time.Time", true
	default:
		if isEnum(col) {
			return enumGoName(col), true // enum type lives in this package
		}
		return "", false // numeric, jsonb, bytea, interval, ... : skip
	}
}

// goNullType returns the null.X type + value accessor for a range bound.
// Only called for IsRangeFilterable columns (numeric/date, name without "id").
func goNullType(col *Column) (typ, accessor string) {
	switch baseType(col) {
	case "timestamptz", "timestamp", "date", "time", "timestamp with time zone", "timestamp without time zone":
		return "null.Time", ".Time"
	case "float8", "float4", "double precision", "double", "real", "numeric", "decimal":
		return "null.Float", ".Float64"
	default: // integer family
		return "null.Int", ".Int64"
	}
}

// cursorCast returns the Postgres cast for a sortable column's cursor value.
func cursorCast(col *Column) string {
	switch baseType(col) {
	case "uuid":
		return "uuid"
	case "timestamptz", "timestamp with time zone":
		return "timestamptz"
	case "timestamp", "timestamp without time zone":
		return "timestamp"
	case "date":
		return "date"
	case "time":
		return "time"
	case "int8", "bigint", "bigserial":
		return "int8"
	case "int4", "integer", "int", "serial":
		return "int4"
	case "int2", "smallint":
		return "int2"
	case "float8", "double precision", "double":
		return "float8"
	case "float4", "real":
		return "float4"
	case "numeric", "decimal":
		return "numeric"
	case "text", "varchar", "bpchar", "char", "citext":
		return "text"
	case "bool", "boolean":
		return "bool"
	default:
		if isEnum(col) {
			return enumQualifiedCast(col)
		}
		return baseType(col)
	}
}

// sortable reports whether a column belongs in the keyset whitelist. Keyset
// needs a total order and stable rows: NOT NULL (a NULL sort key leaks/dupes
// rows across pages), ordered type, and either the PK (tiebreaker) or a
// range-filterable scalar (the columns people actually sort by).
func sortable(col *Column) bool {
	if col.IsVector() || col.Nullable {
		return false
	}
	switch baseType(col) {
	case "jsonb", "json", "bytea":
		return false
	}
	return col.PrimaryKey || col.IsRangeFilterable()
}

func pkLogical(table *Table) string {
	if len(table.PrimaryKeys) > 0 {
		return table.PrimaryKeys[0].Name
	}
	return "id"
}

func lowerFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToLower(s[:1]) + s[1:]
}
